INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1229719-gs318', 'stk-user4760', 'GS 318', 'info', '{"desc": "عليكم السلام و الرحمه …\n\nو الله الدكتور هذا ممكن يعجب فئه معينه و ممكن لا …\n\nبالنسبه كان عندي غيابين …\n\nنظام الدكتور ما يحب المشاركه واجد يعني تشارك على الخفيف …\n\nو الدكتور مستاهل اذا بتغيب ارسل له رساله قبلها و اشرح له ظرفك و راح يتفهم …\n\nميجر ون جبت 19 من 20 و اعطى كل طالب بونص درجه …\n\nميجر تو جبت 16 من 20 و اعطى كل طالب بونص درجتين …\n\nالفايينل جبت 20 من 30 …\n\nالكلاس ورك عنده كوزين كل واحد من خمسه و جبت فيها 8 من عشره …\n\nو عنده كويز بس تيك هوم مخليه زي البحث و جبت فيه 5 من 5\n\nو برزنتشين امره سهلات جبت فيه 5 من 5\n\nالمشاركه و الغياب عليها 10 و اعطاني 10 …\n\nمجموعي تقريبا بين البي و البي بلس …\n\nنزلها في الترانسكربت a …\n\nيعني عطاني فوق حقي …\n\nبس اذا كنت مهتم معاه راح يعطيك اي بلس لو انك جايب العيد و فيه طلاب قالهم بالفاينل انتم اي بلس …\n\nبشكل عام الكلاس ممتع مع الدكتور نواف و اسلوبه مرح بس اهم شي ما تعدا وياه و لا تكون خلني اقولها بالعامي بثر لان فيه بعض الطلاب ما ينعطون وجه …\n\nاتمنى اني افتدك اخوي و نصيحه مني نزل معاه و لا تغيب و صدقني راج تاخذ قريد اكثر من حلو …\n\nالله يوفقك ان شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs-318/145310/2", "user": "user4760", "ts": 1369834287000, "tid": 145310, "pn": 2}}', 1369834287000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1381072-gs318', 'stk-7m00d', 'GS 318', 'info', '{"desc": "انا اخذت 423 عند مارك تومسون و المدرس جدا ابداع و اخلاق الى ابعد الحدود الكوزات جدا سهله و المياجر بعد\nيحدد الكتاب و ما يطلع منه\nالمعلومات المهمه يعيدها تقريبا كل كلاس و المدرس يشرح على اساس ان بعض الطلاب الانقلش عندهم مش كويسه يشرحلك كل معلومه و الكلمه اذا ما فهمت معناها بس ارفع يدك و راح يعلمك وش معناها\n\nالمدرس بصراحه ما اقدر اوفيه حقه اخذت معه كورس 423 و 447\nاخلاقه عاليه و الكلاس ودك انه ما يخلص\n\nانصح بهذا الكورس اذا كان عند مارك تومسون بسسسسسسس\nهذا اللي اقدر افيدك فيه لان 318 ما اخذتها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs-318-or-gs-423/162522/4", "user": "7m00d", "ts": 1403203122000, "tid": 162522, "pn": 4}}', 1403203122000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1448846-gs318', 'stk-user9306', 'GS 318', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nاخوي انا ادري ان السؤال مو موجه لي لكن حبيت اجاوب اذا ممكن :o.\n\nانا حاليا عندي gs-318 والمادة فيها حول 14 الى 15 شابتر وتتكلم عن التاريخ والاحداث الي صارت في الحروب والثورات اذا انت تحب هذا الشيئ وتقدر تعطيه من وقتك الكثير هنا انا انصحك انك تنزلها.\n\nوتجربتي انا مع ذي المادة كانت سيئة جدا لانها خذت من وقتي الكثير واحس الاسئلة في وادي والمتيريال في وادي ثاني ما أنصحك انك تنزلها اذا ما راح تعطيها حقها وتخيل المادة من سمستر 161 صارت الكتاب كامل يعني تقريبا 30 والله يعينك عليها لذلك انا ما انصحك تاخذها ابدا مادة تضيع الوقىت والصعبه(من وجه نظري)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/173262/5", "user": "user9306", "ts": 1463131282000, "tid": 173262, "pn": 5}}', 1463131282000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1208367-gs318', 'stk-chemist', 'GS 318', 'info', '{"desc": "دامك خذيت انجلش 102 عندك مواد gs طب وتخير واحد منها وانصحك كثير ب gs 318 مع الدكتور الرائع والفله نواف المدخلي وتتكلم هذه المادة عن تاريخ العالم من 1500م غلى وقتنا الحاضر والدكتور رحم الله والديه كان مسهلها علينا لابعد الحدود فمن السهل تجيب فيها فوق + b\n\nعندك ics 103 اذا عادك ماخذيتها\n\nعندك xe وأفضل ان تأخذ واحدة بدون لاب علشان مايكون عليك ضغط في اللابات\n\nشوف خطتك الدراسة يمكن تطلع معاك مواد ثانية\n\nالمشكلة اني 28 فما أعرف كثير عن الخطة الجديدة 😐\n\nبالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/123-131/142396/86", "user": "Chemist", "ts": 1365586948000, "tid": 142396, "pn": 86}}', 1365586948000, 1794828444, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
